TEXTS = {lang: {en: v[i] for en, v in _T.items()} for i, lang in enumerate(('fr', 'es', 'de'))}


def translate(lang, ru, en):
    """Text for the Control Center language; keeps the leading/trailing spaces of en."""
    if lang == 'ru':
        return ru
    if lang in TEXTS:
        key = en.strip()
        value = TEXTS[lang].get(key)
        if value is not None:
            return en[:len(en) - len(en.lstrip())] + value + en[len(en.rstrip()):]
    return en
